import math
def prime_factor_count(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return len(factors)

# Check the number of distinct prime factors of N! for a small N.
# Since we are looking at n!, we check pi(n).
def pi(n):
    count = 0
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            count += 1
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return count

# Test small values around the hypothesized limit
print(f"pi(20) = {pi(20)}")
print(f"pi(25) = {pi(25)}")
print(f"pi(30) = {pi(30)}")
